package vn.edu.studymate;
import static org.junit.Assert.*;
import android.content.*;
import android.database.*;
import android.database.sqlite.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import java.util.*;
import vn.edu.studymate.data.DatabaseHelper;
import vn.edu.studymate.model.Entry;

public class NormalizedDatabaseTest {
 Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();
 String file; DatabaseHelper db;long u,v;
 @Before public void setup(){file="normalized-"+System.nanoTime()+".db";db=new DatabaseHelper(c,file);u=db.register("U1","u1@test.vn","Test123!");v=db.register("U2","u2@test.vn","Test123!");}
 @After public void cleanup(){db.close();c.deleteDatabase(file);}
 Entry entry(String kind){Entry e=new Entry();e.kind=kind;e.title="Record "+kind;e.dueAt=System.currentTimeMillis()+3600000;e.endAt=e.dueAt+3600000;return e;}
 long scalar(String sql){try(Cursor c=db.getReadableDatabase().rawQuery(sql,null)){assertTrue(c.moveToFirst());return c.getLong(0);}}
 void rejected(Runnable op){try{op.run();fail("Constraint must reject");}catch(SQLiteConstraintException expected){}}
 @Test public void physicalTablesAndReadOnlyProjection(){for(String t:new String[]{"users","subjects","tasks","class_schedules","exams","reminders","notes","grades"})assertEquals(1,scalar("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='"+t+"'"));assertEquals(0,scalar("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='entries'"));}
 @Test public void reminderRequiresExactlyOneOwnedTarget(){Entry t=entry("task"),e=entry("exam");db.save(u,t);db.save(v,e);SQLiteDatabase sql=db.getWritableDatabase();rejected(()->sql.execSQL("INSERT INTO reminders(user_id,minutes_before) VALUES("+u+",30)"));rejected(()->sql.execSQL("INSERT INTO reminders(user_id,task_id,exam_id,minutes_before) VALUES("+u+","+t.id+","+e.id+",30)"));rejected(()->sql.execSQL("INSERT INTO reminders(user_id,exam_id,minutes_before) VALUES("+u+","+e.id+",30)"));rejected(()->sql.execSQL("INSERT INTO reminders(user_id,task_id,minutes_before) VALUES("+u+",999999,30)"));}
 @Test public void crossOwnerSubjectAndTaskDomainRejectedBySql(){Entry subject=entry("subject"),task=entry("task");db.save(v,subject);db.save(u,task);rejected(()->db.getWritableDatabase().execSQL("UPDATE tasks SET subject_id="+subject.id+" WHERE id="+task.id));rejected(()->db.getWritableDatabase().execSQL("UPDATE tasks SET priority=8 WHERE id="+task.id));rejected(()->db.getWritableDatabase().execSQL("UPDATE tasks SET status='invalid' WHERE id="+task.id));}
 @Test public void multipleRemindersKeepIndependentDeliveryAndCascade(){Entry e=entry("task");e.minutesBefore=30;e.reminderOffsets=Arrays.asList(60,1440,60);db.save(u,e);assertEquals(3,db.reminderOffsets(u,e.id,e.kind).size());List<Entry> reminders=db.scheduledReminders(u);db.markReminderHandled(u,reminders.get(0).reminderId,e.dueAt,1234);assertEquals(e.dueAt,db.scheduledReminders(u).get(0).handledAt);assertEquals(0,db.scheduledReminders(u).get(1).handledAt);e.detail="Edit text preserves stamps";db.save(u,e);assertEquals(e.dueAt,db.scheduledReminders(u).get(0).handledAt);e.dueAt+=60000;db.save(u,e);for(Entry r:db.scheduledReminders(u))assertEquals(0,r.handledAt);db.delete(u,e.id);assertTrue(db.scheduledReminders(u).isEmpty());}
 @Test public void changingPrimaryKeepsChosenOrderAndExistingStamps(){Entry e=entry("task");e.minutesBefore=60;e.reminderOffsets=Arrays.asList(30);db.save(u,e);e.minutesBefore=30;e.reminderOffsets=Arrays.asList(60);db.save(u,e);assertEquals(30,db.get(u,e.id).minutesBefore);assertEquals(Arrays.asList(30,60),db.reminderOffsets(u,e.id,e.kind));}
 @Test public void failedSaveCanBeCorrectedAndRetriedWithoutPhantomId(){Entry s=entry("subject");s.code="DUP";db.save(u,s);Entry duplicate=entry("subject");duplicate.code="DUP";rejected(()->db.save(u,duplicate));assertEquals(0,duplicate.id);duplicate.code="FIX";db.save(u,duplicate);assertEquals(2,db.list(u,"subject").size());Entry e=entry("task");e.reminderOffsets=Arrays.asList(-50);try{db.save(u,e);fail();}catch(IllegalArgumentException expected){}assertEquals(0,e.id);assertTrue(db.list(u,"task").isEmpty());e.reminderOffsets=Arrays.asList(30);db.save(u,e);assertEquals(1,db.list(u,"task").size());}
 @Test public void noDeadlineOrDisabledDoesNotCreateReminders(){Entry t=entry("task");t.dueAt=0;t.reminderOffsets=Arrays.asList(30,60);db.save(u,t);assertTrue(db.reminderOffsets(u,t.id,t.kind).isEmpty());Entry e=entry("exam");e.remindEnabled=false;db.save(u,e);assertTrue(db.reminderOffsets(u,e.id,e.kind).isEmpty());}
 @Test public void userCascadeAndSubjectRestriction(){Entry s=entry("subject");db.save(u,s);Entry t=entry("task");t.subjectId=s.id;db.save(u,t);try{db.delete(u,s.id);fail();}catch(IllegalArgumentException expected){}db.getWritableDatabase().delete("users","id=?",new String[]{""+u});assertEquals(0,scalar("SELECT COUNT(*) FROM tasks WHERE user_id="+u));assertEquals(0,scalar("SELECT COUNT(*) FROM reminders WHERE user_id="+u));}
 @Test public void upgradePreservesAllKindsAndRepairsOnlyInvalidLinks(){String legacy=file+"old";long owner,other;List<Long> ids=new ArrayList<>();try(VersionFourHelper old=new VersionFourHelper(c,legacy)){owner=old.register("Old","old@test.vn","Test123!");other=old.register("Other","other@test.vn","Test123!");for(String k:new String[]{"subject","task","schedule","exam","note","grade"}){Entry e=entry(k);if(!k.equals("subject"))e.subjectId=ids.get(0);ids.add(old.save(owner,e));}Entry bad=entry("task");bad.dueAt=0;bad.remindEnabled=false;ids.add(old.save(owner,bad));old.getWritableDatabase().execSQL("UPDATE entries SET subject_id="+ids.get(0)+",user_id="+other+" WHERE id="+bad.id);}
 try(DatabaseHelper upgraded=new DatabaseHelper(c,legacy)){assertEquals(owner,upgraded.login("old@test.vn","Test123!"));for(int i=0;i<6;i++)assertNotNull(upgraded.get(owner,ids.get(i)));assertEquals(0,upgraded.get(other,ids.get(6)).subjectId);assertTrue(upgraded.reminderOffsets(other,ids.get(6),"task").isEmpty());try(Cursor cursor=upgraded.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM migration_issues",null)){cursor.moveToFirst();assertEquals(1,cursor.getInt(0));}try(Cursor cursor=upgraded.getReadableDatabase().rawQuery("PRAGMA foreign_key_check",null)){assertFalse(cursor.moveToFirst());}Entry next=entry("task");upgraded.save(owner,next);assertTrue(next.id>ids.get(6));}finally{c.deleteDatabase(legacy);}}
 @Test public void failedMigrationRollsBackWithoutDroppingOldData(){String legacy=file+"invalid";try(VersionFourHelper old=new VersionFourHelper(c,legacy)){long owner=old.register("Old","invalid@test.vn","Test123!");Entry e=entry("task");old.save(owner,e);old.getWritableDatabase().execSQL("UPDATE entries SET title='' WHERE id="+e.id);}
 try(DatabaseHelper upgraded=new DatabaseHelper(c,legacy)){try{upgraded.getWritableDatabase();fail("Invalid legacy data must fail atomically");}catch(SQLiteConstraintException expected){}}
 try(SQLiteDatabase sql=SQLiteDatabase.openDatabase(c.getDatabasePath(legacy).getPath(),null,SQLiteDatabase.OPEN_READONLY)){assertEquals(4,sql.getVersion());try(Cursor cursor=sql.rawQuery("SELECT COUNT(*) FROM entries WHERE title=''",null)){cursor.moveToFirst();assertEquals(1,cursor.getInt(0));}}finally{c.deleteDatabase(legacy);}}
}
